-- Schema v2: an unknown (NULL) amount is allowed ONLY for an occurrence generated by a
-- VARIABLE recurring template. v1 already rejected zero/negative amounts and required a
-- recurring template for NULL; this adds the "variable" condition, which needs a lookup
-- and therefore a trigger rather than a CHECK.

CREATE TRIGGER trg_obligation_missing_amount_insert
BEFORE INSERT ON obligations
WHEN NEW.amount_minor IS NULL
BEGIN
    SELECT RAISE(ABORT, 'pm:missing_amount_not_variable')
    WHERE (SELECT amount_mode FROM recurring_templates WHERE id = NEW.recurring_template_id) IS NOT 'variable';
END;

-- An invoice total may be NULL only while it belongs to variable occurrences that are
-- themselves still missing their amount (checked when obligations are linked to it).
CREATE TRIGGER trg_obligation_link_null_total_invoice
BEFORE INSERT ON obligations
WHEN NEW.invoice_id IS NOT NULL
 AND (SELECT total_minor FROM invoices WHERE id = NEW.invoice_id) IS NULL
 AND NEW.amount_minor IS NOT NULL
BEGIN
    SELECT RAISE(ABORT, 'pm:invoice_total_required');
END;

CREATE TRIGGER trg_obligation_relink_null_total_invoice
BEFORE UPDATE OF invoice_id ON obligations
WHEN NEW.invoice_id IS NOT NULL
 AND (SELECT total_minor FROM invoices WHERE id = NEW.invoice_id) IS NULL
 AND NEW.amount_minor IS NOT NULL
BEGIN
    SELECT RAISE(ABORT, 'pm:invoice_total_required');
END;
